func TestHandlerPanicHasErrorLevelStack(t *testing.T) {
	var logs bytes.Buffer
	old := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&logs, &slog.HandlerOptions{Level: slog.LevelInfo})))
	defer slog.SetDefault(old)
	wrapped := playeraccess.RecoverMiddleware(func(*playeraccess.Context, any) (any, error) { panic("b6 handler failure") })
	_, err := wrapped(&playeraccess.Context{PlayerID: 7, MsgID: 11, Seq: 12}, nil)
	if err == nil {
		t.Fatal("panic not recovered")
	}
	got := logs.String()
	if !strings.Contains(got, "level=ERROR") || !strings.Contains(got, "stack=") || !strings.Contains(got, "TestHandlerPanicHasErrorLevelStack") {
		t.Fatalf("panic lacks visible stack: %s", got)
	}
}

// the declared defaults are defaultConfig(): an empty config reads as
// the Config NewServer is given in code, so the default the generator and
// --print-config show is the one that runs.
func TestDeclaredDefaultsAreDefaultConfig(t *testing.T) {
	config, err := configFromViper(viper.New())
	if err != nil {
		t.Fatal(err)
	}
	if config != defaultConfig() {
		t.Fatalf("declared defaults %+v, defaultConfig() %+v", config, defaultConfig())
	}
}

// the dispatch budget follows nest.request_timeout unless it
// is set on its own, and a login budget larger than the dispatch it runs in is
// refused rather than silently cut short.
func TestDispatchBudgetFollowsTheNestRequestTimeout(t *testing.T) {
	cfg := viper.New()
	cfg.Set("nest.request_timeout", "7s")
	config, err := configFromViper(cfg)
	if err != nil {
		t.Fatal(err)
	}
	if config.DispatchTimeout != 7*time.Second || config.LoginTimeout != defaultLoginTimeout {
		t.Fatalf("dispatch=%v login=%v, want 7s and %v", config.DispatchTimeout, config.LoginTimeout, defaultLoginTimeout)
	}
	cfg.Set("nest.request_timeout", "1s")
	if config, err = configFromViper(cfg); err != nil || config.DispatchTimeout != time.Second || config.LoginTimeout != time.Second {
		t.Fatalf("dispatch=%v login=%v err=%v, want both 1s", config.DispatchTimeout, config.LoginTimeout, err)
	}
	cfg.Set("player_access.tcp.dispatch_timeout", "3s")
	cfg.Set("player_access.tcp.login_timeout", "5s")
	if _, err := configFromViper(cfg); err == nil {
		t.Fatal("a login budget larger than the dispatch budget was accepted")
	}
}

// player_access.tcp.* is read strictly. A value of the wrong type used to
// be read as false / 0 (the default) / nanoseconds and pass every check; Init
// now refuses it and names the key, and a valid value written as a string (an
// environment override) still reads.
func TestConfigValuesOfTheWrongTypeAreRefusedByName(t *testing.T) {
	newMod := func() *Mod {
		return &Mod{authenticator: AuthenticatorFunc(func(context.Context, string, net.Addr) (gateway.Principal, error) {
			return gateway.Principal{}, nil
		})}
	}
	yamlConfig := func(t *testing.T, text string) *viper.Viper {
		t.Helper()
		cfg := viper.New()
		cfg.SetConfigType("yaml")
		if err := cfg.ReadConfig(strings.NewReader(text)); err != nil {
			t.Fatal(err)
		}
		return cfg
	}
	for _, tc := range []struct{ name, yaml, key string }{
		{"enabled_on", "player_access:\n  tcp:\n    enabled: on\n", "player_access.tcp.enabled"},
		{"payload_8k", "player_access:\n  tcp:\n    max_payload_bytes: 8k\n", "player_access.tcp.max_payload_bytes"},
		{"handshake_bytes_negative", "player_access:\n  tcp:\n    max_handshake_bytes: -1\n", "player_access.tcp.max_handshake_bytes"},
		{"connections_fraction", "player_access:\n  tcp:\n    max_connections: 1.5\n", "player_access.tcp.max_connections"},
		{"idle_unitless", "player_access:\n  tcp:\n    idle_timeout: 90\n", "player_access.tcp.idle_timeout"},
		{"handshake_word", "player_access:\n  tcp:\n    handshake_timeout: soon\n", "player_access.tcp.handshake_timeout"},
		{"nest_request_unitless", "nest:\n  request_timeout: 7\n", "nest.request_timeout"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			mod := newMod()
			err := mod.Init(yamlConfig(t, tc.yaml))
			if err == nil || !strings.Contains(err.Error(), tc.key) {
				t.Errorf("%s: Init returned %v, want a refusal naming %s (parsed config: %+v)", strings.TrimSpace(tc.yaml), err, tc.key, mod.config)
			}
		})
	}
	mod := newMod()
	valid := "player_access:\n  tcp:\n    enabled: \"true\"\n    max_payload_bytes: \"65536\"\n    max_handshake_bytes: 4096\n    idle_timeout: 30s\n"
	if err := mod.Init(yamlConfig(t, valid)); err != nil {
		t.Fatalf("valid config refused: %v", err)
	}
	if !mod.config.Enabled || mod.config.MaxPayloadBytes != 65536 || mod.config.MaxHandshakeBytes != 4096 || mod.config.IdleTimeout != 30*time.Second {
		t.Fatalf("valid config read as %+v", mod.config)
	}
}

// A limit outside its bounds is refused by its key,
// and a limit bounded by another names that one too, so the operator knows
// which line to change. Before, every limit shared one sentence ("addr,
// limits and timeouts are outside safe bounds", and "timeouts exceed safe
// bounds" for the upper bounds of the timeouts).
func TestAnOutOfBoundsSettingIsRefusedByName(t *testing.T) {
	const key = "player_access.tcp."
	for _, tc := range []struct {
		name string
		set  map[string]any
		want []string
	}{
		{"addr_without_port", map[string]any{"addr": "localhost"}, []string{key + "addr"}},
		{"connections_above_the_hard_cap", map[string]any{"max_connections": 2000000}, []string{key + "max_connections = 2000000"}},
		{"connections_negative", map[string]any{"max_connections": -1}, []string{key + "max_connections = -1"}},
		{"per_ip_above_connections", map[string]any{"max_connections": 2000, "max_connections_per_ip": 3000}, []string{key + "max_connections_per_ip = 3000", key + "max_connections = 2000"}},
		{"handshakes_above_connections", map[string]any{"max_connections": 1000, "max_handshakes": 2000}, []string{key + "max_handshakes = 2000", key + "max_connections = 1000"}},
		{"handshake_bytes_above_64k", map[string]any{"max_handshake_bytes": 100000}, []string{key + "max_handshake_bytes = 100000"}},
		{"handshake_timeout_above_a_minute", map[string]any{"handshake_timeout": "2m"}, []string{key + "handshake_timeout = 2m0s"}},
		{"idle_timeout_negative", map[string]any{"idle_timeout": "-1s"}, []string{key + "idle_timeout = -1s"}},
		{"dispatch_timeout_above_five_minutes", map[string]any{"dispatch_timeout": "10m"}, []string{key + "dispatch_timeout = 10m0s"}},
		{"login_above_dispatch", map[string]any{"dispatch_timeout": "1s", "login_timeout": "2s"}, []string{key + "login_timeout = 2s", key + "dispatch_timeout = 1s"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			cfg := viper.New()
			for name, value := range tc.set {
				cfg.Set(key+name, value)
			}
			_, err := configFromViper(cfg)
			if err == nil {
				t.Fatalf("%v accepted", tc.set)
			}
			for _, want := range tc.want {
				if !strings.Contains(err.Error(), want) {
					t.Errorf("%v refused with %q, want it to name %q", tc.set, err, want)
				}
			}
			if strings.Contains(err.Error(), "safe bounds") {
				t.Errorf("%v refused with the unnamed sentence: %q", tc.set, err)
			}
		})
	}
	if _, err := configFromViper(viper.New()); err != nil {
		t.Fatalf("the defaults are refused: %v", err)
	}
}

// the Mod declares player_access.tcp.shutdown_timeout as its
// stop budget, so the App grants the listener that long inside
// shutdown.total_timeout instead of the 3s floor of an undeclared Mod.
func TestTheModDeclaresItsShutdownTimeoutAsTheStopBudget(t *testing.T) {
	mod := NewMod()
	provider, ok := any(mod).(interface{ StopBudget() time.Duration })
	if !ok {
		t.Fatal("the player tcp Mod declares no stop budget: the App gives it only the 3s floor of an undeclared Mod")
	}
	if got := provider.StopBudget(); got != 0 {
		t.Fatalf("stop budget before Init = %v, want 0 (not declared)", got)
	}
	mod.authenticator = AuthenticatorFunc(func(context.Context, string, net.Addr) (gateway.Principal, error) { return gateway.Principal{}, nil })
	for _, tc := range []struct {
		configured string
		want       time.Duration
	}{{"", 10 * time.Second}, {"7s", 7 * time.Second}} {
		cfg := viper.New()
		if tc.configured != "" {
			cfg.Set("player_access.tcp.shutdown_timeout", tc.configured)
		}
		if err := mod.Init(cfg); err != nil {
			t.Fatal(err)
		}
		if got := provider.StopBudget(); got != tc.want {
			t.Errorf("shutdown_timeout %q: stop budget = %v, want %v", tc.configured, got, tc.want)
		}
	}
}

// the Mod keeps the server after a Stop that ran out of
// time, so the retry has something to wait for.
func TestAModStopRetryKeepsTheServerUntilItDrains(t *testing.T) {
	server, release, _, returned := stalledAuthServer(t)
	runtime := NewRuntime(nil, defaultLoginTimeout)
	mod := &Mod{config: defaultConfig(), server: server, transportRuntime: runtime}
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	first := mod.StopWithContext(ctx)
	cancel()
	if !errors.Is(first, context.DeadlineExceeded) || mod.server != server {
		t.Fatalf("first StopWithContext = %v, server kept = %v", first, mod.server == server)
	}
	close(release)
	if err := mod.StopWithContext(context.Background()); err != nil {
		t.Fatalf("retry StopWithContext = %v", err)
	}
	select {
	case <-returned:
	default:
		t.Fatal("retry StopWithContext reported success while the authenticator was still running")
	}
	if mod.server != nil {
		t.Fatal("the drained server is still held")
	}
}

// stalledAuthServer 使用正式 NewServer，认证回调故意忽略 ctx，以验证 Mod 在超时后保留所有权。
func stalledAuthServer(t *testing.T) (*gateway.TCPServer, chan struct{}, <-chan struct{}, <-chan struct{}) {
	t.Helper()
	config := defaultConfig()
	config.Addr = "127.0.0.1:0"
	config.HandshakeTimeout = 5 * time.Second
	release, entered, returned := make(chan struct{}), make(chan struct{}, 1), make(chan struct{})
	server, err := NewServer(config, &accessplayer.Runtime{Protocols: playeraccess.NewProtocolRegistry()}, AuthenticatorFunc(func(context.Context, string, net.Addr) (gateway.Principal, error) {
		entered <- struct{}{}
		<-release
		time.Sleep(100 * time.Millisecond)
		close(returned)
		return gateway.Principal{}, gateway.ErrUnauthenticated
	}))
	if err != nil {
		t.Fatal(err)
	}
	if err := server.Start(); err != nil {
		t.Fatal(err)
	}
	conn, err := net.Dial("tcp", server.Addr().String())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = conn.Close() })
	if err := wire.Write(conn, []*wire.Packet{{MsgID: 0, Seq: 1, Payload: []byte("token")}}, int(config.MaxHandshakeBytes)); err != nil {
		t.Fatal(err)
	}
	select {
	case <-entered:
	case <-time.After(2 * time.Second):
		t.Fatal("handshake did not reach authenticator")
	}
	return server, release, entered, returned
}

// 真实 RS v2 客户端夹具供 SDK、Sync/Lockstep 的生成消费者测试复用。
func dialAuthenticated(t *testing.T, server *gateway.TCPServer, token string) net.Conn {
	t.Helper()
	conn, err := net.Dial("tcp", server.Addr().String())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = conn.Close() })
	if err := wire.Write(conn, []*wire.Packet{{MsgID: 0, Seq: 1, Payload: []byte(token)}}, wire.DefaultMaxPayload); err != nil {
		t.Fatal(err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
	ack, err := wire.Read(conn, wire.DefaultMaxPayload)
	if err != nil {
		t.Fatal(err)
	}
	if ack.MsgID != 0 || ack.Seq != 1 || len(ack.Payload) != 0 {
		t.Fatalf("unexpected auth ACK: %+v", ack)
	}
	return conn
}
